mapper.select:
select * from
(select rownum rn,m.* from
(select * from inbound where webuser_id=#{webuser_id}
and approval_status = 'REQUEST'
order by inbound_id desc) m)
where rn>=#{startRow} and rn<=#{endRow}

select * from
(select rownum rn,m.* from
(select * from outbound where approval_status = 'REQUEST' and webuser_id=#{webuser_id}
order by outbound_id desc) m)
where rn>=#{startRow} and rn<=#{endRow}

mapper.update:
update inbound_detail
set approval_status=#{approval_status},
reason=#{reason, jdbcType=VARCHAR}
where inbound_detail_id=#{inbound_detail_id}

update outbound_detail
set approval_status=#{approval_status},
reason=#{reason, jdbcType=VARCHAR}
where outbound_detail_id=#{outbound_detail_id}

mapper.select:
select * from
(
select rownum rn, p.* from approval p

order by approval_id desc
)

where rn >= #{startRow} and rn <= #{endRow}

select * from
(
select rownum rn, p.* from approval p
where bound_type = #{boundType}
order by approval_id desc
)

where rn >= #{startRow} and rn <= #{endRow}

select product_name
from product
where product_id = #{productId}
